# Story tables are `const` in the scripts (read-only in GDScript). The scripts listed here get the table renamed to
# DEFAULT_<NAME> and a mutable copy `var <NAME> = DEFAULT_<NAME>.duplicate(true)` right after it, so that the
# Strings autoload can replace text from story/strings.txt. Nothing else in the code changes.
PATCHABLE = {
    "scripts/story.gd": ["DAYS", "VIGNETTES"], "scripts/playbook.gd": ["BOOKS", "PROBLEMS"], "scripts/owner.gd": ["CARDS"],
    "scripts/msp.gd": ["PROBLEMS", "RANSOM", "ADOBE", "INSTALL"],
    "scripts/talk.gd": ["GREETINGS", "SMALL", "GOSSIP", "TIPS_GENERIC", "OWNER_HOLD", "VIC_GREETINGS", "VIC_SMALL", "VIC_GOSSIP", "VIC_TIPS", "VIC_STATE", "VIC_ASK"],
    "scripts/nerds.gd": ["JOKES", "THREADS"], "scripts/lync.gd": ["MESSAGES", "VIC_MESSAGES", "VIC_PRESENCE"],
    "scripts/review.gd": ["QUOTES", "OWNER_QUOTES", "EPILOGUES"], "scripts/social.gd": ["THANKS"],
    "scripts/shift.gd": ["WEEK_TRAFFIC", "REASONS", "PAGES"], "scripts/hints.gd": ["DAY1"], "scripts/career.gd": ["MEDALS", "UNLOCKS"],
    "scripts/build.gd": ["QUIRKS", "PRESETS", "INFO"], "scripts/events.gd": ["DECK"], "scripts/mutators.gd": ["MUTATORS", "STARTS"], "scripts/yeartwo.gd": ["CARRY", "YEAR2", "TEXT"], "scripts/growth.gd": ["STRETCH"], "scripts/conference.gd": ["TEXT", "ROUNDS", "VENDORS", "CHATS"], "scripts/printer_game.gd": ["TEXT", "QUESTIONS", "MODEL_TEXT"], "scripts/onsite.gd": ["TEXT", "JOBS", "MORE_JOBS", "EVENTS", "STAFF", "SITE_APPS", "PETS", "FINDINGS", "MEETINGS"],
    "scripts/outings.gd": ["SONGS", "FRIEND_HINTS", "HERRINGS", "RECIPE_TIPS", "GUESTS", "CREW_LINES", "KARAOKE_TEXT"],
    "scripts/sales_campaign.gd": ["BEAT_TEXT"],
    "scripts/difficulty.gd": ["COZY_TEXT"],
}


# Functions whose story strings are replaced by Strings.t("Inline.<Script>.<function>.<n>", "<the text>") so the text
# can be edited in story/strings.txt (the default stays in the code).
INLINE = {}  # (an experiment: moving the strings inside the game logic out of the code; not used)
def _literals(line):
    """(start, end, body) of every double-quoted string literal on a source line (end is exclusive)"""
    found = []
    i = 0
    while i < len(line):
        c = line[i]
        if c == "#":
            break
        if c == '"':
            j = i + 1
            while j < len(line) and line[j] != '"':
                j += 2 if line[j] == "\\" else 1
            if j >= len(line):
                break
            found.append((i, j + 1, line[i + 1:j]))
            i = j
        i += 1
    return found


def externalize(text, script, funcs):
    lines = text.split("\n")
    out = []
    current = None
    count = 0
    for line in lines:
        if line.startswith("func "):
            name = line[5:].split("(")[0]
            current = name if name in funcs else None
            count = 0
        elif line and not line.startswith((" ", "	")) and current:
            current = None
        if current and not line.lstrip().startswith("#"):
            pieces = []
            last = 0
            for start, end, body in _literals(line):
                before = line[:start].rstrip()
                skip = (
                    len(body) < 10 or " " not in body or "\\" in body or before.endswith(("Strings.t(", "preload(", "load("))
                    or body.startswith(("res://", "user://"))
                )
                pieces.append(line[last:start])
                if skip:
                    pieces.append(line[start:end])
                else:
                    count += 1
                    pieces.append('Strings.t("Inline.%s.%s.%d", "%s")' % (script, current, count, body))
                last = end
            pieces.append(line[last:])
            line = "".join(pieces)
            # an autoload's return type is not known while the scripts are parsed: give the variable its type
            line = re.sub(r"^(\s*)var (\w+) := (\(?Strings\.t\()", r"\1var \2: String = \3", line)
        out.append(line)
    return "\n".join(out)


def _depth(line):
    """net bracket depth of a source line, ignoring strings and comments"""
    d = 0
    in_str = False
    i = 0
    while i < len(line):
        c = line[i]
        if in_str:
            if c == "\\":
                i += 1
            elif c == '"':
                in_str = False
        elif c == '"':
            in_str = True
        elif c == "#":
            break
        elif c in "[{(":
            d += 1
        elif c in "]})":
            d -= 1
        i += 1
    return d


# these files declare the mutable copies after the last constant instead of next to each table
PATCH_LATE = {"scripts/career.gd"}
NO_PATCH_HEADER = {"scripts/events.gd"}  # its header already lists max-line-length only; nothing else needed


def make_patchable(text, names, late=False, header=True):
    lines = text.split("\n")
    out = []
    late_vars = []
    i = 0
    while i < len(lines):
        line = lines[i]
        hit = None
        for name in names:
            if line.startswith("const %s := " % name):
                hit = name
        if hit:
            kind = "Dictionary" if line.split(":= ", 1)[1].lstrip().startswith("{") else "Array"
            block = [line.replace("const %s := " % hit, "const DEFAULT_%s := " % hit, 1)]
            depth = _depth(line)
            while depth > 0:
                i += 1
                block.append(lines[i])
                depth += _depth(lines[i])
            out.extend(block)
            var_line = "var %s: %s = DEFAULT_%s.duplicate(true)" % (hit, kind, hit)
            if late:
                late_vars.append(var_line)
            else:
                out.append(var_line)
        else:
            out.append(line)
        i += 1
    if late:
        k = next(n for n, ln in enumerate(out) if ln.startswith("var ") or ln.startswith("func "))
        out[k:k] = late_vars + [""]
    result = "\n".join(out)
    if late or not header:
        return result
    # the mutable copies are upper case variables declared next to their constants
    first, rest = result.split("\n", 1)
    return first + "\n# gdlint:disable=class-definitions-order,class-variable-name\n" + rest


def write(rel, text):
    if rel in INLINE:
        text = externalize(text, os.path.basename(rel)[:-3].capitalize(), INLINE[rel])
    if rel in PATCHABLE:
        text = make_patchable(text, PATCHABLE[rel], rel in PATCH_LATE, rel not in NO_PATCH_HEADER)
    path = os.path.normpath(os.path.join(ROOT, rel))
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", newline="\n") as f:
        f.write(text)
    print("wrote", rel)


